const pako = require('pako');
const polyfill = require('../public/base64')
const {atob, btoa} = polyfill;

function base64ToUint8Array(base64) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

function uint8ArrayToBase64(uint8Array) {
    let binaryString = '';
    for (let i = 0; i < uint8Array.length; i++) {
        binaryString += String.fromCharCode(uint8Array[i]);
    }
    return btoa(binaryString);
}

// 示例字符串
//const input = '"timestamp": 1730381066251--data:image/svg+xml;base64,';
const input = '{ throw inflator.msg || msg[inflator.err]; }';

// 压缩成 zlib 格式
const compressed = pako.deflate(base64ToUint8Array(input), { to: 'string' });
console.log('压缩后的数据:', compressed);

// 压缩成 gzip 格式
const compressedGzip = pako.gzip(input, { to: 'string' });
console.log('gzip 压缩后的数据:', compressedGzip);

const decompressed = pako.inflate(compressed, { to: 'string' });
console.log('解压后的数据:', decompressed);

// 解压缩 gzip 格式
const decompressedGzip = pako.ungzip(compressedGzip, { to: 'string' });
console.log('gzip 解压后的数据:', decompressedGzip);